INSERT INTO questions (id, code, section_id, parent_question_id, question, ref, ref_text, refs, depends_on_question_id, depends_on_value, sort_order) VALUES
('S 01', 'S 01', 2, NULL, 'Les préparations pharmaceutiques réalisées garantissent une qualité constante, appropriée à leur usage, conformément aux exigences des BPP', '1.01', 'Afin de protéger la santé humaine, les préparations pharmaceutiques sont réalisées de façon à garantir une qualité constante, appropriée à leur usage. Pour atteindre cet objectif elles sont réalisées en conformité avec les exigences définies dans le présent texte.', '1.01', NULL, NULL, 1),
('Q001', 'Q001', 2, NULL, 'Il existe un Système d''Assurance Qualité', '1.02', 'Les pharmacies à usage intérieur et les pharmacies d''officine disposent d’un système d’assurance qualité qui intègre l’ensemble des règles de bonnes pratiques présentées dans ce texte. Ce système est documenté et contrôlé et son efficacité est surveillée.', '1.02', NULL, NULL, 2),
('Q002', 'Q002', 2, NULL, 'Ce système est documenté (MAQ, Procédures, Modes Opératoires, Enregistrements ...)', '1.02', 'Les pharmacies à usage intérieur et les pharmacies d''officine disposent d’un système d’assurance qualité qui intègre l’ensemble des règles de bonnes pratiques présentées dans ce texte. Ce système est documenté et contrôlé et son efficacité est surveillée.', '1.02', 'Q001', 'oui', 3),
('Q003', 'Q003', 2, NULL, 'Ce système est controlé (auto-inspection, audits,..)', '1.02', 'Les pharmacies à usage intérieur et les pharmacies d''officine disposent d’un système d’assurance qualité qui intègre l’ensemble des règles de bonnes pratiques présentées dans ce texte. Ce système est documenté et contrôlé et son efficacité est surveillée.', '1.02, 1.05', 'Q001', 'oui', 4),
('Q004', 'Q004', 2, NULL, 'Des indicateurs qualités sont identifiés et suivis', '1.02', 'Les pharmacies à usage intérieur et les pharmacies d''officine disposent d’un système d’assurance qualité qui intègre l’ensemble des règles de bonnes pratiques présentées dans ce texte. Ce système est documenté et contrôlé et son efficacité est surveillée.', '1.02, 1.05', 'Q001', 'oui', 5),
('Q005', 'Q005', 3, NULL, 'Le Système d''Assurance Qualité est basé sur les "Bonnes Pratiques de Préparation" publiées par l''ANSM en 2023 (documents qualités intégrant les BPP)', '1.03', 'Les concepts fondamentaux de la gestion de la qualité, des Bonnes Pratiques de Préparation (BPP) et de la gestion du risque sont étroitement liés. Ils sont décrits ci-après en vue de souligner leurs relations réciproques et leur importance fondamentale dans la production et le contrôle des
préparations pharmaceutiques.', '1.03, 1.04, 1.06, 1.07, 1.02', 'Q001', 'oui', 6),
('Q006', 'Q006', 3, NULL, 'Il existe un Système de Gestion Documentaire', '1.05', 'Le système d’assurance qualité est soumis à une évaluation de son efficacité et de son adéquation entre le présent texte et les pratiques mises en oeuvre :
-un système documentaire est mis en place et maîtrisé ;
-les préparations sont formulées et réalisées selon l’état des connaissances scientifiques, médicales et pharmaceutiques ;
-les procédés de préparation et de contrôle sont clairement décrits et les règles figurant dans le présent texte sont appliquées ;
-une fois réalisées, les préparations n’entrent dans le circuit de dispensation qu’une fois contrôlées et libérées conformément aux procédures établies ;
-des dispositions sont prises pour garantir la qualité des préparations jusqu’à leur date de péremption et leur délai limite d’utilisation après ouverture.', '1.05', NULL, NULL, 7),
('Q007', 'Q007', 3, NULL, 'Le système d''assurance qualité est connu du personnel impliqué dans la production', '1.05', 'Le système d’assurance qualité est soumis à une évaluation de son efficacité et de son adéquation entre le présent texte et les pratiques mises en oeuvre :
-un système documentaire est mis en place et maîtrisé ;
-les préparations sont formulées et réalisées selon l’état des connaissances scientifiques, médicales et pharmaceutiques ;
-les procédés de préparation et de contrôle sont clairement décrits et les règles figurant dans le présent texte sont appliquées ;
-une fois réalisées, les préparations n’entrent dans le circuit de dispensation qu’une fois contrôlées et libérées conformément aux procédures établies ;
-des dispositions sont prises pour garantir la qualité des préparations jusqu’à leur date de péremption et leur délai limite d’utilisation après ouverture.', '1.05', 'Q001', 'oui', 8),
('Q008', 'Q008', 3, NULL, 'Les préparations pharmaceutiques sont formulées et réalisées selon l’état des connaissances scientifiques, médicales et pharmaceutiques et l''analyse y conduisant est tracée (exemple de dossier de préparation suivant annexe)', '1.05', 'Le système d’assurance qualité est soumis à une évaluation de son efficacité et de son adéquation entre le présent texte et les pratiques mises en oeuvre :
-un système documentaire est mis en place et maîtrisé ;
-les préparations sont formulées et réalisées selon l’état des connaissances scientifiques, médicales et pharmaceutiques ;
-les procédés de préparation et de contrôle sont clairement décrits et les règles figurant dans le présent texte sont appliquées ;
-une fois réalisées, les préparations n’entrent dans le circuit de dispensation qu’une fois contrôlées et libérées conformément aux procédures établies ;
-des dispositions sont prises pour garantir la qualité des préparations jusqu’à leur date de péremption et leur délai limite d’utilisation après ouverture.', '1.05', NULL, NULL, 9),
('Q009', 'Q009', 5, NULL, 'Des revues qualité sont organisées selon une périodicité définie après analyse des réclamations et des non-conformité', '1.10', 'Après analyse des réclamations et des non-conformités, il est recommandé de réaliser des revues qualités portant notamment sur les préparations pour lesquelles un écart ou une modification substantielle a été relevée. Ces revues sont menées afin de vérifier la répétabilité des procédés existants, la pertinence des spécifications initialement décrites dans le dossier de préparation (cf. Annexe II) pour les MPUP, les articles de conditionnement, les produits intermédiaires et les préparations terminées. Ces revues permettent de mettre en évidence toute évolution et d’identifier les améliorations à apporter aux produits et aux procédés. Elles alimentent l’analyse globale du risque lié à la préparation et sont normalement menées et documentées selon une périodicité appropriée et justifiée. Elles prennent en compte les revues précédentes. Elles comprennent notamment le suivi des éléments suivants :
-Les MPUP et les articles de conditionnement utilisés pour la préparation, notamment ceux provenant de nouvelles sources d’approvisionnement, ainsi que la traçabilité de la chaîne d’approvisionnement des substances actives ;
-les résultats des contrôles qualité des préparations terminées ;
-les lots non conformes aux spécifications établies ainsi que les investigations correspondantes ;
-les déviations significatives et les non-conformités, les investigations correspondantes et l''efficacité des actions correctives et préventives prises en conséquence ;
-les modifications intervenues sur les procédés ou sur les méthodes d''analyse ;
-les retours, réclamations et rappels liés à des problèmes de qualité ainsi que les investigations correspondantes ;
-la pertinence de toute mesure corrective antérieure relative au procédé de préparation ou aux équipements ;
-la qualification des principaux équipements et de leurs utilités, par exemple les installations de traitement de l’air, de production et de distribution de l’eau ou de gaz comprimés ;
-les contrats et/ou cahiers des charges et/ou plannings de maintenance technique afin de s''assurer qu''ils sont à jour.', '1.10', NULL, NULL, 10),
('Q010', 'Q010', 5, NULL, 'Les revues qualités sont documentées', '1.10', 'Après analyse des réclamations et des non-conformités, il est recommandé de réaliser des revues qualités portant notamment sur les préparations pour lesquelles un écart ou une modification substantielle a été relevée. Ces revues sont menées afin de vérifier la répétabilité des procédés existants, la pertinence des spécifications initialement décrites dans le dossier de préparation (cf. Annexe II) pour les MPUP, les articles de conditionnement, les produits intermédiaires et les préparations terminées. Ces revues permettent de mettre en évidence toute évolution et d’identifier les améliorations à apporter aux produits et aux procédés. Elles alimentent l’analyse globale du risque lié à la préparation et sont normalement menées et documentées selon une périodicité appropriée et justifiée. Elles prennent en compte les revues précédentes. Elles comprennent notamment le suivi des éléments suivants :
-Les MPUP et les articles de conditionnement utilisés pour la préparation, notamment ceux provenant de nouvelles sources d’approvisionnement, ainsi que la traçabilité de la chaîne d’approvisionnement des substances actives ;
-les résultats des contrôles qualité des préparations terminées ;
-les lots non conformes aux spécifications établies ainsi que les investigations correspondantes ;
-les déviations significatives et les non-conformités, les investigations correspondantes et l''efficacité des actions correctives et préventives prises en conséquence ;
-les modifications intervenues sur les procédés ou sur les méthodes d''analyse ;
-les retours, réclamations et rappels liés à des problèmes de qualité ainsi que les investigations correspondantes ;
-la pertinence de toute mesure corrective antérieure relative au procédé de préparation ou aux équipements ;
-la qualification des principaux équipements et de leurs utilités, par exemple les installations de traitement de l’air, de production et de distribution de l’eau ou de gaz comprimés ;
-les contrats et/ou cahiers des charges et/ou plannings de maintenance technique afin de s''assurer qu''ils sont à jour.', '1.10', 'Q009', 'oui', 11),
('Q011', 'Q011', 5, NULL, 'Les revues qualités alimentent l''analyse globale de risque', '1.10', 'Après analyse des réclamations et des non-conformités, il est recommandé de réaliser des revues qualités portant notamment sur les préparations pour lesquelles un écart ou une modification substantielle a été relevée. Ces revues sont menées afin de vérifier la répétabilité des procédés existants, la pertinence des spécifications initialement décrites dans le dossier de préparation (cf. Annexe II) pour les MPUP, les articles de conditionnement, les produits intermédiaires et les préparations terminées. Ces revues permettent de mettre en évidence toute évolution et d’identifier les améliorations à apporter aux produits et aux procédés. Elles alimentent l’analyse globale du risque lié à la préparation et sont normalement menées et documentées selon une périodicité appropriée et justifiée. Elles prennent en compte les revues précédentes. Elles comprennent notamment le suivi des éléments suivants :
-Les MPUP et les articles de conditionnement utilisés pour la préparation, notamment ceux provenant de nouvelles sources d’approvisionnement, ainsi que la traçabilité de la chaîne d’approvisionnement des substances actives ;
-les résultats des contrôles qualité des préparations terminées ;
-les lots non conformes aux spécifications établies ainsi que les investigations correspondantes ;
-les déviations significatives et les non-conformités, les investigations correspondantes et l''efficacité des actions correctives et préventives prises en conséquence ;
-les modifications intervenues sur les procédés ou sur les méthodes d''analyse ;
-les retours, réclamations et rappels liés à des problèmes de qualité ainsi que les investigations correspondantes ;
-la pertinence de toute mesure corrective antérieure relative au procédé de préparation ou aux équipements ;
-la qualification des principaux équipements et de leurs utilités, par exemple les installations de traitement de l’air, de production et de distribution de l’eau ou de gaz comprimés ;
-les contrats et/ou cahiers des charges et/ou plannings de maintenance technique afin de s''assurer qu''ils sont à jour.', '1.10', 'Q009', 'oui', 12),
('Q012', 'Q012', 6, NULL, 'L''appréciation du risque de la préparation pharmaceutique est réalisée (bénéfice/risque), permettant de décider si des mesures de réduction du risque doivent être mises en œuvre, ou si le risque existant peut être accepté', '1.11', 'L’appréciation du rapport bénéfice/risque permet d’évaluer les dangers potentiels et sert de base pour décider si des mesures de réduction des risques sont à appliquer, ou si le risque existant peut être accepté.', '1.11', NULL, NULL, 13),
('Q013', 'Q013', 6, NULL, 'Une analyse pharmaceutique et réglementaire est réalisée pour chaque type de préparation (annexe I)', '1.12', 'Quel que soit le risque associé à la réalisation d''une préparation et préalablement à sa réalisation, une analyse pharmaceutique est réalisée par le pharmacien qui reçoit la demande. Un exemple d’outil d’aide à l’analyse pharmaceutique et réglementaire est proposé (cf. Annexe I).', '1.12', NULL, NULL, 14),
('Q014', 'Q014', 6, NULL, 'L''analyse pharmaceutique et réglementaire pour chaque type de préparation (annexe I) est réalisée et en cas de refus un critère explicite est tracé pour justifier la non réalisation', '1.20', 'Le pharmacien refuse de réaliser et de dispenser une préparation s''il estime que celle-ci n''est pas conforme à l''état des connaissances scientifiques, médicales et pharmaceutiques et/ou que celle-ci est dangereuse au regard de l’appréciation du risque décrit ci-dessus.', '1.20', 'Q013', 'oui', 15),
('Q015', 'Q015', 6, NULL, 'En cas d’impossibilité de réalisation de préparation, un contrat de sous-traitance est établi en amont, selon les modalités décrites par par le présent texte.', '1.19', 'Si le pharmacien n''est pas en mesure de réaliser la préparation, il la sous-traite selon la réglementation en vigueur et dans les conditions prévues par le présent texte.', '1.19', NULL, NULL, 16),
('Q016', 'Q016', 6, NULL, 'En cas d’impossibilité de réalisation d''une préparation, la notification et/ou proposition d''alternative au prescripteur est tracée', '1.21', 'En cas d’impossibilité de réalisation de la préparation, il le notifie et propose au prescripteur et/ou donneur d’ordre, si possible, une alternative.', '1.21', NULL, NULL, 17),
('Q017', 'Q017', 6, NULL, 'Une analyse de risque simplifiée est réalisée pour les préparations demandées en urgence', '1.22', 'Pour le cas des demandes exceptionnelles de préparations en urgence, une évaluation du risque, ainsi qu’une fiche d’instruction de préparation, sont réalisées. Les éléments du dossier de préparation sont complétés a posteriori. Dans tous les cas, un dossier de lot accompagne la préparation.', '1.22', NULL, NULL, 18),
('Q018', 'Q018', 6, NULL, 'L''analyse technico-réglementaire des préparations est réalisée (annexe II partie 1) avant toute décision de réalisation', '1.13', 'Une évaluation de la valeur ajoutée et de la faisabilité technique de la préparation est réalisée.
* la valeur ajoutée est estimée en considérant pour chaque préparation notamment :
- l''intérêt pharmaco-thérapeutique ;
- la meilleure acceptabilité possible pour une observance renforcée ;
- l’appréciation du bénéfice/risque.
* la faisabilité technique est estimée en considérant pour chaque préparation :
- la présence de procédures générales et de modes opératoires ;
- la présence de matériel et locaux conformes à la réalisation de la forme pharmaceutique ;
- la présence d’un personnel formé ;
- une analyse de la formule de la préparation.', '1.13, 1.15, 5.41', 'Q013', 'oui', 19),
('Q019', 'Q019', 6, NULL, 'L''analyse technico-réglementaire des préparations prend en compte la réglementation en vigueur (interdictions, restrictions, Formulaire National…)', '1.17', 'La réalisation d’une préparation n’est entreprise qu''après vérification par le pharmacien de sa conformité aux textes en vigueur (notamment au regard de certaines décisions d''interdiction ou de restriction de préparation ou d’inscription sur la liste des substances vénéneuses). Dans le cas où une
préparation est inscrite au Formulaire national de la Pharmacopée française, le pharmacien se conforme à la monographie en vigueur.', '1.17', 'Q013', 'oui', 20),
('Q020', 'Q020', 6, NULL, 'Des analyses de risques concernant l''intégralité du processus de préparation sont réalisées (annexe III)', '1.11', 'L’appréciation du rapport bénéfice/risque permet d’évaluer les dangers potentiels et sert de base pour décider si des mesures de réduction des risques sont à appliquer, ou si le risque existant peut être accepté.', '1.11, 4.05, 5.13, 5.23', NULL, NULL, 21),
('Q021', 'Q021', 6, NULL, 'Une analyse de risque est réalisée pour classer la préparation en risque faible, moyen ou élevé, selon les critères de l''annexe III (substance active, voie d''administration, forme pharmaceutique, opérations réalisées, nombre de patients), permettant de la classer en risque faible, moyen ou élevé', '1.16', 'L’évaluation du risque de la préparation permet de définir les niveaux d’exigences adaptés à la réalisation de cette dernière. Cette évaluation prend en compte notamment la substance active, la voie d''administration, la forme pharmaceutique, les opérations pharmaceutiques réalisées et le nombre de patients potentiels pour lesquels la préparation est réalisée.
Un tableau permettant une catégorisation des préparations pharmaceutiques est proposé (cf. Annexe III).
La classification des préparations en 3 catégories facilite l’application des conditions requises pour l’exécution et le contrôle des préparations.
Elle permet de discriminer les préparations susceptibles de présenter directement ou indirectement un danger pour la santé : risque faible, risque moyen et risque élevé, en fonction des paramètres critiques de la préparation. Le niveau de production annuel est un facteur susceptible de minorer ou de majorer le risque au regard de l’effectif du groupe de patients amené à recevoir la préparation.', '1.16, 5.23', NULL, NULL, 22),
('Q022', 'Q022', 6, NULL, 'Dans le cadre de l''analyse de risque pour classer la préparation, le niveau de risque « produit » (contamination microbiologique pour le patient) et le niveau de risque « personnel/environnement » (toxicité, CMR, produits biologiques/OGM) sont identifiés et distingués pour chaque produit.', 'LD1.026', 'Deux types de risques sont identifiés :
- le risque « produit » c’est-à-dire pour la préparation et donc pour le patient. C’est le risque de contamination microbiologique ;
- le risque pour le personnel et pour l’environnement :
o Les substances actives toxiques comme les médicaments présentant des risques Cancérogène Mutagène Reprotoxique (CMR) répertoriés ou dont les données scientifiques démontrent un risque toxique (par exemple les médicaments antibiotiques, cytotoxiques, antiviraux et radiopharmaceutiques) ;
o Les médicaments d’origine biologique et les médicaments composés en tout ou partie d’Organismes Génétiquement Modifiés (OGM) y compris lorsqu’ils sont des médicaments de thérapie innovante (MTI).', 'LD1.026', 'Q021', 'oui', 23),
('Q023', 'Q023', 6, NULL, 'Une analyse de risque toxicologique de la préparation est réalisée, appuyée sur une recherche bibliographique sur les substances actives et excipients', '4.32', 'Une évaluation du risque lié à la préparation est effectuée par la pharmacie qui la réalise. Une recherche bibliographique appropriée permet de connaître les données toxicologiques et cliniques relatives aux substances actives et aux excipients de la préparation.', '4.32', NULL, NULL, 24),
('Q024', 'Q024', 6, NULL, 'Une analyse de risque relative à la réattribution des préparations est réalisée', '5.61', 'On entend par réattribution des préparations terminées la dispensation d’une préparation à un patient alors qu’elle était initialement destinée à un autre patient. Elle fait l’objet d’une analyse de risque et d’une procédure.', '5.61, 5.63', NULL, NULL, 25),
('Q025', 'Q025', 6, NULL, 'Le niveau de contrôle qualité appliqué est justifié par référence à l''analyse de risque réalisée pour chaque préparation de la préparation (cf. art. 1.16)', '6.59', 'Les contrôles à effectuer sont fonction de l’évaluation du risque, basée sur les critères suivants : •  le type de préparation pharmaceutique : extemporanée et/ou pouvant être stockée ; •  la destination de la préparation ou du lot de préparations : préparation destinée à un seul patient ou lot destiné à plusieurs patients ; •  la forme pharmaceutique réalisée ; •  la classification de la préparation au regard de l’Annexe III ou d’une analyse de risque formalisée ; •  le type d’opération pharmaceutique nécessaire à la réalisation de la préparation ; •  le nombre d’unités préparées ; •  le caractère destructif ou non des opérations de contrôle.', '6.59', 'Q021', 'oui', 26),
('Q026', 'Q026', 6, NULL, 'Une analyse du risque d''interactions contenant-contenu est conduite (excipients à risque, données littérature/fournisseur/internes), avec recherche documentée de l''absence d''interaction.', '6.85', 'L''absence d''interactions contenant-contenu doit être recherchée. Une analyse du risque d''interactions est conduite en se basant notamment sur la présence d''excipients à risque dans la formule (agents de surface, solutions hydroalcooliques, excipients lipidiques ou lipophiles...). Les données disponibles sont recherchées à partir des données de la littérature, des données fournisseurs, ou de données issues de recherches développées et validées en interne par l''établissement.', '6.85', NULL, NULL, 27),
('Q027', 'Q027', 6, NULL, 'Une analyse de risque est réalisée pour la conception et de l’aménagement des locaux (matière première utilisée /procédé utilisé)', '3.19', 'Les risques de contamination varient en fonction de la MPUP et du procédé utilisés. Ils sont pris en compte lors de la conception et de l’aménagement des locaux.', '3.19, 5.18, 5.19, 5.20, 5.21, 5.22', NULL, NULL, 28),
('Q028', 'Q028', 6, NULL, 'Une analyse de risque documentée justifie le d''une choix zone (plutôt que local dédié) pour les catégories 1-3 non stériles/non CMR', '3.15', 'Pour la réalisation des préparations de catégories 1, 2 et 3 (cf. annexe n°III) non stériles ou non cancérogènes, mutagènes ou génotoxiques (CMR), l’utilisation de zones est possible.', '3.15', NULL, NULL, 29),
('Q029', 'Q029', 6, NULL, 'La stratégie de libération repose sur une évaluation du risque formalisée et documentée.', '6.70', 'La stratégie de libération des préparations est fondée sur une évaluation du risque appropriée.', '6.70', NULL, NULL, 30),
('Q030', 'Q030', 6, NULL, 'Une analyse de risque préalable et documentée est réalisée pour le choix des installations et des équipements de préparation stérile', 'LD1.034', 'Le choix des installations et équipements fait l’objet d’une analyse de risques préalable et documentée, prenant en compte la nature des produits manipulés,la protection des personnes et de l’environnement.', 'LD1.034, 5.18, 5.19, 5.20, 5.21, 5.22', NULL, NULL, 31),
('Q031', 'Q031', 6, NULL, 'L''analyse de risque pour le choix des équipement et l''environnement se base sur les niveaux de risque produit et de la nature des manipulations', 'LD1.027', 'Pour chacun de ces deux risques, il est possible d’individualiser des niveaux qui conditionnent le choix de l’équipement et de l’environnement.', 'LD1.027, LD1.028, LD1.029, LD1.030, LD1.031', 'Q030', 'oui', 32),
('Q032', 'Q032', 6, NULL, 'Une analyse de risque préalable est  réalisée pour le procédé de stérilisation de contact à l''intérieur de l''isolateur', 'LD1.076', 'La mise en oeuvre du procédé de stérilisation de contact des surfaces à l’intérieur de l’isolateur garantissant la décontamination nécessite une analyse de risque préalable et est soumise à un processus de validation adapté. Ce procédé de stérilisation par contact doit garantir l’intégrité du fonctionnement de l’équipement.', 'LD1.076', NULL, NULL, 33),
('Q033', 'Q033', 6, NULL, 'Une analyse de risques est réalisée pour l''élaboration du plan d''échantillonnage', 'LD1.150', 'Un plan d’échantillonnage est défini et comprend l’analyse d’échantillons volumétriques d’air et des contrôles de surface. Il tient compte d’une analyse de risques, des normes ISO en vigueur et définit notamment les lieux, la fréquence et le nombre de prélèvements.', 'LD1.150', NULL, NULL, 34),
('Q034', 'Q034', 6, NULL, 'Une analyse de risque est réalisée si les limites de surveillance microbiologique des ZAC ne tiennent pas compte des recommandations décrites dans le tableau 9 (LD1)', 'LD1.154', 'Les limites concernant la surveillance microbiologique des ZAC décrites dans le tableau 9 sont données à titre de recommandations.', 'LD1.154', NULL, NULL, 35),
('Q035', 'Q035', 6, NULL, 'Une analyse des risques professionnels est réalisé par l''employeur', 'LD2.012', 'L’employeur est responsable de la sécurité du personnel travaillant dans les zones de préparation. Il associe à l’analyse de risque le pharmacien désigné comme responsable des préparations.', 'LD2.012', NULL, NULL, 36),
('Q036', 'Q036', 6, NULL, 'L''analyse des risques professionnels permet l''élaboration du Document Unique des Risques Professionnes (DUERP), accessible par l''ensemble du personnel', 'LD2.012', 'L’employeur est responsable de la sécurité du personnel travaillant dans les zones de préparation. Il associe à l’analyse de risque le pharmacien désigné comme responsable des préparations.', 'LD2.012', 'Q035', 'oui', 37),
('Q037', 'Q037', 6, NULL, 'Le PRP est associé à la réalisation et l''actualisation du DUERP', 'LD2.012', 'L’employeur est responsable de la sécurité du personnel travaillant dans les zones de préparation. Il associe à l’analyse de risque le pharmacien désigné comme responsable des préparations.', 'LD2.012', 'Q035', 'oui', 38),
('Q038', 'Q038', 6, NULL, 'Une analyse de risque est réalisée, le cas écheant si un même équipement est partagé entre préparations biologiques et chimiques non CMR', 'LD2.019', 'Des locaux différents avec un niveau de confinement adapté correspondant à l’activité la plus à risque sont dédiés notamment pour l’activité de :
* Préparations non stériles contenant des substances pouvant présenter un risque pour la santé et l’environnement. Dans le cas où l’organisation des locaux de préparation ne permet pas d’avoir un local dédié à la réalisation des préparations non stériles contenant des substances pouvant présenter un risque pour la santé et l’environnement, l’utilisation de zones dédiées peut être envisagée en fonction du risque. Dans ce cas, les zones garantissent un niveau de confinement adapté au risque d’exposition.
* Préparations stériles contenant des substances pouvant présenter un risque pour la santé et l’environnement avec deux types de locaux :
- un local pour les préparations contenant des substances chimiques pouvant présenter un risque pour la santé et l’environnement,
- un local pour les préparations contenant des substances biologiques (par exemple la reconstitution des Médicaments de Thérapie Innovante (MTI) ou la mise sous forme appropriée des Médicaments de Thérapie Innovante Préparés Ponctuellement (MTIPP) et chimique (non CMR). Les équipements utilisés sont différents pour les préparations biologiques et les préparations chimiques. A défaut un même équipement
peut être utilisé en fonction de l’analyse de risque. Il n’est pas possible de réaliser des préparations non stériles dans les mêmes locaux que les préparations stériles.', 'LD2.019', NULL, NULL, 39),
('Q039', 'Q039', 6, NULL, 'Une analyse de risque spécifique est réalisée pour les manipulations présentant un risque de dispersion d''OGM', 'LD2.021', 'Les manipulations des médicaments qui comportent des risques potentiels de dispersion d’OGM identifiés à partir de l’analyse de risque spécifique sont effectuées sous des postes à flux d’air unidirectionnel de type II ou des isolateurs. Ainsi, la décongélation hors d’une poste à flux d’air unidirectionnel de type II ou des isolateurs est possible pour les médicaments OGM de classe de confinement C1 si les contenants ne nécessitent pas d’être ouverts. Règlement n°1394/2007du parlement européen et du conseil du 13 novembre 2007 concernant les médicaments de thérapie innovante 43 Article L. 5121-1 du  CSP - alinéa 17', 'LD2.021', NULL, NULL, 40),
('Q040', 'Q040', 6, NULL, 'Une analyse de risque est réalisée pour le choix des EPC / EPI en fonction du type de substances manipulées', 'LD2.015', 'L’habillage et les équipements de protection sont adaptés à l''usage et au risque potentiel encouru, y compris au cours des opérations de nettoyage ou de maintenance réalisées à l’intérieur de la zone de préparation. Les mêmes dispositions sont prises lors du changement de matériel.', 'LD2.015, LD2.036, LD2.041, LD2.042', NULL, NULL, 41),
('Q041', 'Q041', 6, NULL, 'Une analyse des risques est réalisée pour déterminer la fréquence de changement des gants', 'LD2.040', 'La qualité des gants, seul contact direct entre le produit et l’opérateur, assure une protection maximale pour le risque de contact cutané. La fréquence de changement des gants est déterminée en fonction de l''analyse des risques. Lorsque le type de danger est « danger cutané », le choix du type de gants est obligatoirement adapté au produit manipulé, en fonction de leur épaisseur et de leur perméabilité.', 'LD2.040', NULL, NULL, 42),
('Q042', 'Q042', 8, NULL, 'Le système documentaire mis en place (papier ou électronique) est', '4.01', 'Une documentation exhaustive, révisée, imprimée ou sur support électronique est un outil de transmission et de conservation de l''information essentiel au système qualité pharmaceutique. Elle permet d’assurer la conformité des opérations aux exigences du présent texte. Que le support soit électronique ou papier, il est nécessaire que le système soit protégé contre des modifications non autorisées, contre les pertes de données et que les données demeurent disponibles pendant toute la durée de conservation exigée pour les documents.', '4.01, 4.06', 'Q006', 'oui', 43),
('Q042.01', 'Q042.01', 8, 'Q042', 'protégé pour éviter toute modification non autorisée', '4.01', 'Une documentation exhaustive, révisée, imprimée ou sur support électronique est un outil de transmission et de conservation de l''information essentiel au système qualité pharmaceutique. Elle permet d’assurer la conformité des opérations aux exigences du présent texte. Que le support soit électronique ou papier, il est nécessaire que le système soit protégé contre des modifications non autorisées, contre les pertes de données et que les données demeurent disponibles pendant toute la durée de conservation exigée pour les documents.', '4.01, 4.06', 'Q006', 'oui', 44),
('Q042.02', 'Q042.02', 8, 'Q042', 'sauvegardé sur un 2ème support de sauvegarde pour éviter la perte de données', '4.01', 'Une documentation exhaustive, révisée, imprimée ou sur support électronique est un outil de transmission et de conservation de l''information essentiel au système qualité pharmaceutique. Elle permet d’assurer la conformité des opérations aux exigences du présent texte. Que le support soit électronique ou papier, il est nécessaire que le système soit protégé contre des modifications non autorisées, contre les pertes de données et que les données demeurent disponibles pendant toute la durée de conservation exigée pour les documents.', '4.01', 'Q006', 'oui', 45),
('Q042.03', 'Q042.03', 8, 'Q042', 'et les données restent disponible pendant toute la durée de conservation exigée par les documents', '4.01', 'Une documentation exhaustive, révisée, imprimée ou sur support électronique est un outil de transmission et de conservation de l''information essentiel au système qualité pharmaceutique. Elle permet d’assurer la conformité des opérations aux exigences du présent texte. Que le support soit électronique ou papier, il est nécessaire que le système soit protégé contre des modifications non autorisées, contre les pertes de données et que les données demeurent disponibles pendant toute la durée de conservation exigée pour les documents.', '4.01', 'Q006', 'oui', 46),
('Q043', 'Q043', 8, NULL, 'L''ensemble de la documentation nécessaire et relative à l''activité du personnel (dossier papier ou logiciel de gestion documentaire) est rapidement accessible', '4.01', 'Une documentation exhaustive, révisée, imprimée ou sur support électronique est un outil de transmission et de conservation de l''information essentiel au système qualité pharmaceutique. Elle permet d’assurer la conformité des opérations aux exigences du présent texte. Que le support soit électronique ou papier, il est nécessaire que le système soit protégé contre des modifications non autorisées, contre les pertes de données et que les données demeurent disponibles pendant toute la durée de conservation exigée pour les documents.', '4.01', 'Q006', 'oui', 47),
('Q044', 'Q044', 8, NULL, 'Il existe un logiciel de gestion documentaire', '4.03', 'En fonction des risques identifiés par l’établissement, il peut être mis en place un système informatisé pour gérer les aspects documentaires et la réalisation des préparations pharmaceutiques.', '4.03', 'Q006', 'oui', 48),
('Q045', 'Q045', 8, NULL, 'La sauvegarde et restauration du logiciel de gestion documentaire est testée et vérifiée', '4.01', 'Une documentation exhaustive, révisée, imprimée ou sur support électronique est un outil de transmission et de conservation de l''information essentiel au système qualité pharmaceutique. Elle permet d’assurer la conformité des opérations aux exigences du présent texte. Que le support soit électronique ou papier, il est nécessaire que le système soit protégé contre des modifications non autorisées, contre les pertes de données et que les données demeurent disponibles pendant toute la durée de conservation exigée pour les documents.', '4.01', 'Q044', 'oui', 49),
('Q046', 'Q046', 8, NULL, 'Les documents existent sous forme électronique et/ou papier', '4.06', 'Tous les types de documents sont définis et respectés. Les exigences s’appliquent de la même manière à toutes formes de supports documentaires mis en oeuvre. De nombreux documents peuvent exister sous des formes hybrides, c’est-à-dire avec certains éléments sous forme électronique et d’autres sous forme papier. Des contrôles appropriés sont mis en place pour garantir l’intégrité des enregistrements pendant leur durée d’utilisation et d’archivage.', '4.06', 'Q006', 'oui', 50),
('Q047', 'Q047', 8, NULL, 'Il existe un logiciel pour la réalisation des préparations', '4.03', 'En fonction des risques identifiés par l’établissement, il peut être mis en place un système informatisé pour gérer les aspects documentaires et la réalisation des préparations pharmaceutiques.', '4.03', NULL, NULL, 51),
('Q048', 'Q048', 9, NULL, 'Il existe une procédure de gestion documentaire', '4.04', 'La documentation est gérée par une procédure de maîtrise des documents qui intègre et respecte le cadre fixé par les règles générales de gestion documentaire définies au sein de l’établissement.', '4.04', 'Q006', 'oui', 52),
('Q049', 'Q049', 9, NULL, 'La procédure de gestion documentaire couvre explicitement le cycle de vie complet (création, validation, diffusion, révision, archivage, destruction) de chaque type de document', '4.04', 'La documentation est gérée par une procédure de maîtrise des documents qui intègre et respecte le cadre fixé par les règles générales de gestion documentaire définies au sein de l’établissement.', '4.04', 'Q048', 'oui', 53),
('Q050', 'Q050', 9, NULL, 'La procédure de gestion documentaire prévoit la mise à jour et la diffusion des documents en prenant en compte les risques liés à la reproduction des documents qualité', '4.07', 'La reproduction des documents ne permet pas l''introduction d''une quelconque erreur au cours du processus de reproduction. Une vigilance particulière est apportée pour la diffusion et l’utilisation de version à jour.', '4.07', 'Q048', 'oui', 54),
('Q051', 'Q051', 9, NULL, 'La procédure des gestion documentaitre précise le circuit de validation des documents qui sont', '4.08', 'Les documents sont approuvés, signés et datés. Ils sont établis par des personnes autorisées. Le contenu des documents n''est pas ambigu et est identifiable de façon unique. La date de prise d''effet est définie.', '4.08', 'Q048', 'oui', 55),
('Q051.01', 'Q051.01', 9, 'Q051', 'rédigés par une personne identifiée et autorisée', '4.08', 'Les documents sont approuvés, signés et datés. Ils sont établis par des personnes autorisées. Le contenu des documents n''est pas ambigu et est identifiable de façon unique. La date de prise d''effet est définie.', '4.08', 'Q048', 'oui', 56),
('Q051.02', 'Q051.02', 9, 'Q051', 'vérifiés par une personne identifiée et autorisée', '4.08', 'Les documents sont approuvés, signés et datés. Ils sont établis par des personnes autorisées. Le contenu des documents n''est pas ambigu et est identifiable de façon unique. La date de prise d''effet est définie.', '4.08', 'Q048', 'oui', 57),
('Q051.03', 'Q051.03', 9, 'Q051', 'approuvés par une personne identifiée et autorisée', '4.08', 'Les documents sont approuvés, signés et datés. Ils sont établis par des personnes autorisées. Le contenu des documents n''est pas ambigu et est identifiable de façon unique. La date de prise d''effet est définie.', '4.08', 'Q048', 'oui', 58),
('Q052', 'Q052', 9, NULL, 'La procédure de gestion documentaire prévoit une révision régulière des documents', '4.10', 'Les documents inclus dans le système de gestion de la qualité sont régulièrement révisés et tenus à jour.', '4.10', 'Q048', 'oui', 59),
('Q053', 'Q053', 9, NULL, 'Les procédures validées sont diffusées spécifiquement aux personnels concernées (logiciel de gestion documentaire, diffusion papier, réunion de service avec compte rendu…)', '2.04', 'Le personnel a accès à toute la documentation nécessaire relative à son activité.', '2.04', 'Q006', 'oui', 60),
('Q054', 'Q054', 9, NULL, 'Le personnel a accès à la documentation relative à son activité', '4.04', 'La documentation est gérée par une procédure de maîtrise des documents qui intègre et respecte le cadre fixé par les règles générales de gestion documentaire définies au sein de l’établissement.', '4.04, 2.01, 2.04, 6.29', 'Q006', 'oui', 61),
('Q055', 'Q055', 9, NULL, 'Le mode de diffusion des documents garantit une preuve de prise de connaissance individuelle par chaque membre du personnel concerné', '4.04', 'La documentation est gérée par une procédure de maîtrise des documents qui intègre et respecte le cadre fixé par les règles générales de gestion documentaire définies au sein de l’établissement.', '4.04, 2.01', 'Q006', 'oui', 62),
('Q056', 'Q056', 9, NULL, 'Les procédures applicables dans la ZAC sont communiquées est connue des personnes étrangères à la PUI autorisées par le PRP / gérant PUI  à entrer dans les zones de préparation, de contrôle et de stockage', 'LD1.116', 'Le personnel extérieur amené à pénétrer dans ces locaux (ex : personnel de sociétés d’entretien, de construction ou de nettoyage) est informé des procédures applicables dans la ZAC et les respecte.', 'LD1.116, 3.05', 'Q006', 'oui', 63),
('Q057', 'Q057', 9, NULL, 'Il existe système de déclaration/documentation relative aux écarts qualité des produits', '4.05', 'Il convient de documenter tout évènement significatif ayant trait à la qualité des produits, y compris les appréciations du risque et les justificatifs ayant conduit aux variations par rapport aux exigences figurant dans le présent texte.', '4.05', NULL, NULL, 64),
('Q058', 'Q058', 9, NULL, 'Le système de déclaration /documentation relative aux écarts de qualité des produits est utilisé en pratique (ex : nombre de déclarations sur les 12 derniers mois)', '4.05', 'Il convient de documenter tout évènement significatif ayant trait à la qualité des produits, y compris les appréciations du risque et les justificatifs ayant conduit aux variations par rapport aux exigences figurant dans le présent texte.', '4.05', 'Q057', 'oui', 65),
('Q059', 'Q059', 9, NULL, 'Des contrôles des enregistrements (durée d''utilisation et archivage) sont réalisés', '4.06', 'Tous les types de documents sont définis et respectés. Les exigences s’appliquent de la même manière à toutes formes de supports documentaires mis en oeuvre. De nombreux documents peuvent exister sous des formes hybrides, c’est-à-dire avec certains éléments sous forme électronique et d’autres sous forme papier. Des contrôles appropriés sont mis en place pour garantir l’intégrité des enregistrements pendant leur durée d’utilisation et d’archivage.', '4.06', 'Q006', 'oui', 66),
('Q060', 'Q060', 9, NULL, 'La date de rédaction du document qualité est enregistrée', '4.08', 'Les documents sont approuvés, signés et datés. Ils sont établis par des personnes autorisées. Le contenu des documents n''est pas ambigu et est identifiable de façon unique. La date de prise d''effet est définie.', '4.08', 'Q006', 'oui', 67),
('Q061', 'Q061', 9, NULL, 'La date de mise en application du document qualité est enregistrée', '4.08', 'Les documents sont approuvés, signés et datés. Ils sont établis par des personnes autorisées. Le contenu des documents n''est pas ambigu et est identifiable de façon unique. La date de prise d''effet est définie.', '4.08', 'Q006', 'oui', 68),
('Q062', 'Q062', 9, NULL, 'Les documents sont présentées de façon ordonnées (codification prévue dans la procedure de gestion documentaire)', '4.09', 'Les documents sont présentés de façon ordonnée et sont faciles à vérifier. Les procédures, les instructions de travail et les modes opératoires sont écrits dans un style obligatoirement directif.', '4.09', 'Q006', 'oui', 69),
('Q063', 'Q063', 9, NULL, 'Le style directif est obligatoirement utilisé pour les procédures, les instructions de travail et les modes opératoires', '4.09', 'Les documents sont présentés de façon ordonnée et sont faciles à vérifier. Les procédures, les instructions de travail et les modes opératoires sont écrits dans un style obligatoirement directif.', '4.09', 'Q006', 'oui', 70),
('Q064', 'Q064', 9, NULL, 'La périodicité de révision des documents qualité est  définie par type de document, avec une alerte automatique ou un suivi des échéances de révision dépassées', '4.10', 'Les documents inclus dans le système de gestion de la qualité sont régulièrement révisés et tenus à jour.', '4.10', 'Q006', 'oui', 71),
('Q065', 'Q065', 9, NULL, 'En cas de documentation papier, les documents sont :', '4.02', 'Des documents clairs et lisibles évitent les erreurs inhérentes aux communications orales et garantissent la traçabilité de la préparation pharmaceutique. Les données manuscrites sont limitées et validées.', '4.02', 'Q006', 'oui', 72),
('Q065.01', 'Q065.01', 9, 'Q065', 'Dactylographiés', '4.02', 'Des documents clairs et lisibles évitent les erreurs inhérentes aux communications orales et garantissent la traçabilité de la préparation pharmaceutique. Les données manuscrites sont limitées et validées.', '4.02', 'Q006', 'oui', 73),
('Q065.02', 'Q065.02', 9, 'Q065', 'Avec de rares entrées manuscrites validées', '4.02', 'Des documents clairs et lisibles évitent les erreurs inhérentes aux communications orales et garantissent la traçabilité de la préparation pharmaceutique. Les données manuscrites sont limitées et validées.', '4.02', 'Q006', 'oui', 74),
('Q066', 'Q066', 9, NULL, 'Les enregistrements manuscrits sont limités.', '4.11', 'Les documents ne sont pas manuscrits ; toutefois, lorsqu''un document nécessite l''inscription de données, l''espace qui leur est réservé est suffisant. Les saisies manuscrites sont faites de manière claire, lisible et indélébile. Le cas échéant leur(s) auteur(s) est identifié(s) ainsi que la date du relevé.', '4.11', 'Q006', 'oui', 75),
('Q066.01', 'Q066.01', 9, 'Q066', 'Ils sont lisibles', '4.11', 'Les documents ne sont pas manuscrits ; toutefois, lorsqu''un document nécessite l''inscription de données, l''espace qui leur est réservé est suffisant. Les saisies manuscrites sont faites de manière claire, lisible et indélébile. Le cas échéant leur(s) auteur(s) est identifié(s) ainsi que la date du relevé.', '4.11', 'Q006', 'oui', 76),
('Q066.02', 'Q066.02', 9, 'Q066', 'Ils sont indélébiles', '4.11', 'Les documents ne sont pas manuscrits ; toutefois, lorsqu''un document nécessite l''inscription de données, l''espace qui leur est réservé est suffisant. Les saisies manuscrites sont faites de manière claire, lisible et indélébile. Le cas échéant leur(s) auteur(s) est identifié(s) ainsi que la date du relevé.', '4.11', 'Q006', 'oui', 77),
('Q066.03', 'Q066.03', 9, 'Q066', 'Leur auteur est identifié', '4.11', 'Les documents ne sont pas manuscrits ; toutefois, lorsqu''un document nécessite l''inscription de données, l''espace qui leur est réservé est suffisant. Les saisies manuscrites sont faites de manière claire, lisible et indélébile. Le cas échéant leur(s) auteur(s) est identifié(s) ainsi que la date du relevé.', '4.11', 'Q006', 'oui', 78),
('Q066.04', 'Q066.04', 9, 'Q066', 'Leur date/horaire de rédaction est tracé', '4.11', 'Les documents ne sont pas manuscrits ; toutefois, lorsqu''un document nécessite l''inscription de données, l''espace qui leur est réservé est suffisant. Les saisies manuscrites sont faites de manière claire, lisible et indélébile. Le cas échéant leur(s) auteur(s) est identifié(s) ainsi que la date du relevé.', '4.11', 'Q006', 'oui', 79),
('Q067', 'Q067', 9, NULL, 'Il existe des procédures générales', '4.12', 'Les documents nécessaires sont :
- les procédures générales qui donnent les indications nécessaires à la réalisation et à l’organisation de l’ensemble des opérations ;
- les dossiers de préparation qui permettent la création des instructions de préparation (fiches de préparation), de conditionnement et de contrôle ;
- les dossiers de lot, comprenant notamment les enregistrements.', '4.12, 1.07', 'Q006', 'oui', 80),
('Q068', 'Q068', 9, NULL, 'Il existe des dossiers de préparation (modes opératoires, fiches de fabrication)', '4.12', 'Les documents nécessaires sont :
- les procédures générales qui donnent les indications nécessaires à la réalisation et à l’organisation de l’ensemble des opérations ;
- les dossiers de préparation qui permettent la création des instructions de préparation (fiches de préparation), de conditionnement et de contrôle ;
- les dossiers de lot, comprenant notamment les enregistrements.', '4.12, 1.07, 5.01, 5.06', 'Q006', 'oui', 81),
('Q069', 'Q069', 9, NULL, 'Un dossier de prépration est réalisé pour chaque type de préparation ; il reprend la validité technico réglementaire, et comprend : la préparation et son procédé, les spécifications, contrôles et éléments d''assurance qualité (annexe II parties 1,2,3)', '1.14', 'D’un point de vue pratique, un dossier de préparation en trois parties est à rédiger afin de regrouper toutes les informations nécessaires au bon déroulement de la préparation (cf. Annexe II).', '1.14, 1.18, 4.30, 5.01', 'Q006', 'oui', 82),
('Q070', 'Q070', 9, NULL, 'Un dossier de préparation est réalisé pour plusieurs préparations de même composition qualitative quand les procédés de préparation et les méthodes de contrôle sont identiques', '4.31', 'Le dossier de préparation peut être réalisé pour plusieurs préparations de même composition qualitative quand les procédés de préparation et les méthodes de contrôle sont identiques. Il est rédigé par la pharmacie qui réalise la préparation.', '4.31', 'Q006', 'oui', 83),
('Q071', 'Q071', 9, NULL, 'Il existe des dossiers de lot (enregistrements)', '4.12', 'Les documents nécessaires sont :
- les procédures générales qui donnent les indications nécessaires à la réalisation et à l’organisation de l’ensemble des opérations ;
- les dossiers de préparation qui permettent la création des instructions de préparation (fiches de préparation), de conditionnement et de contrôle ;
- les dossiers de lot, comprenant notamment les enregistrements.', '4.12, 1.07, LD1.145', 'Q006', 'oui', 84),
('Q072', 'Q072', 10, NULL, 'Il existe une (des) procédure(s) relative(s) aux opérations de préparation', '1.05', 'Le système d’assurance qualité est soumis à une évaluation de son efficacité et de son adéquation entre le présent texte et les pratiques mises en oeuvre :
-un système documentaire est mis en place et maîtrisé ;
-les préparations sont formulées et réalisées selon l’état des connaissances scientifiques, médicales et pharmaceutiques ;
-les procédés de préparation et de contrôle sont clairement décrits et les règles figurant dans le présent texte sont appliquées ;
-une fois réalisées, les préparations n’entrent dans le circuit de dispensation qu’une fois contrôlées et libérées conformément aux procédures établies ;
-des dispositions sont prises pour garantir la qualité des préparations jusqu’à leur date de péremption et leur délai limite d’utilisation après ouverture.', '1.05, 4.13, 5.01', 'Q006', 'oui', 85),
('Q073', 'Q073', 10, NULL, 'La(les) procédure(s) relative(s) aux opérations de préparation précise(nt) qu''il est nécessaire de', '5.34', 'Il est nécessaire de :
- ne réaliser qu’une seule préparation à la fois, sur une même zone de travail, afin d’éviter les risques d’erreurs et de contaminations croisées ;
- confier préférentiellement à la même personne qualifiée au sens du CSP la totalité des opérations d’un lot de préparation ;
- ne pas interrompre cette personne avant la réalisation complète de la préparation ;
- respecter l’ensemble des procédures et instructions établies par écrit ;
- consigner par écrit dans le dossier de lot de la préparation toutes les données utiles à la garantie de sa qualité : les enregistrements sont effectués au moment où chaque action est réalisée.', '5.34', 'Q072', 'oui', 86),
('Q073.01', 'Q073.01', 10, 'Q073', 'ne réaliser qu’une seule préparation à la fois, sur une même zone de travail, afin d’éviter les risques d’erreurs et de contaminations croisées', '5.34', 'Il est nécessaire de :
